-- New duel-format progress starts here; historical matches are not imported.
create table duel_format_achievement_launch(singleton boolean primary key default true check(singleton),started_at timestamptz not null default now());
create table duel_format_achievement_events(match_id uuid not null references amateur_duel_match(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,primary key(match_id,user_id));
create table duel_format_achievement_state(user_id uuid not null references users(id) on delete cascade,format text not null check(format in ('express','mix','classic','sniper','marathon-4','marathon-7','rhythm')),wins integer not null check(wins>=0),streak integer not null check(streak>=0),best_streak integer not null check(best_streak>=streak),primary key(user_id,format));
create table duel_format_achievement_totals(user_id uuid not null references users(id) on delete cascade,achievement_id text not null references achievements(id),value integer not null check(value>=0),updated_at timestamptz not null,primary key(user_id,achievement_id));
