insert into duel_format_achievement_launch(singleton) values(true);
insert into achievements(id,photo_url,title,description,requirement,category,availability,future_tag,reward_currency,reward_stars,reward_experience,reward_tokens,sort_order) values
('duel-format-express-wins','/achievements/duel-formats/express-wins-v1.webp?v=20260906-hd1','Победы · Экспресс','В коротком периоде важен каждый бросок. Держи высокую результативность и заканчивай «Экспресс» с победным счётом.','Выиграть 1 дуэль в формате «Экспресс».','duel','active',null,0,3,3,0,4000),
('duel-format-express-streak','/achievements/duel-formats/express-streak-v1.webp?v=20260906-hd1','Победная серия · Экспресс','Найди свой темп в коротких дуэлях и удержи его на несколько побед подряд. Соперники меняются, задача остаётся прежней.','Выиграть 2 дуэли подряд в формате «Экспресс».','duel','active',null,0,5,5,0,4001),
('duel-format-mix-wins','/achievements/duel-formats/mix-wins-v1.webp?v=20260906-hd1','Победы · Микс','Сначала серия бросков на точность, затем период на скорость. Справься с обеими задачами и забери дуэль.','Выиграть 1 дуэль в формате «Микс».','duel','active',null,0,3,3,0,4002),
('duel-format-mix-streak','/achievements/duel-formats/mix-streak-v1.webp?v=20260906-hd1','Победная серия · Микс','Двух разных периодов достаточно, чтобы проверить и расчёт, и скорость. Повторяй успешное сочетание в следующих встречах.','Выиграть 2 дуэли подряд в формате «Микс».','duel','active',null,0,5,5,0,4003),
('duel-format-classic-wins','/achievements/duel-formats/classic-wins-v1.webp?v=20260906-hd1','Победы · Классика','Три периода дают сопернику время отыграться. Распредели силы и сохрани преимущество к окончанию классической дуэли.','Выиграть 1 дуэль в формате «Классика».','duel','active',null,0,3,3,0,4004),
('duel-format-classic-streak','/achievements/duel-formats/classic-streak-v1.webp?v=20260906-hd1','Победная серия · Классика','После трёх периодов и финального счёта тебя ждёт новая встреча. Продолжай выигрывать классические дуэли одну за другой.','Выиграть 2 дуэли подряд в формате «Классика».','duel','active',null,0,5,5,0,4005),
('duel-format-sniper-wins','/achievements/duel-formats/sniper-wins-v1.webp?v=20260906-hd1','Победы · Снайпер','В «Снайпере» важна стоимость каждого гола. Выбирай сложные броски и набирай больше очков, чем соперник.','Выиграть 1 дуэль в формате «Снайпер».','duel','active',null,0,3,3,0,4006),
('duel-format-sniper-streak','/achievements/duel-formats/sniper-streak-v1.webp?v=20260906-hd1','Победная серия · Снайпер','Один удачный сложный бросок помогает взять дуэль. Для серии побед понадобится регулярно подтверждать свою меткость.','Выиграть 2 дуэли подряд в формате «Снайпер».','duel','active',null,0,5,5,0,4007),
('duel-format-marathon-4-wins','/achievements/duel-formats/marathon-4-wins-v1.webp?v=20260906-hd1','Победы · Марафон · 4 секунды','Четыре секунды на новый гол оставляют мало времени на раздумья. Держи высокий темп и закончи дуэль впереди соперника.','Выиграть 1 дуэль в формате «Марафон · 4 секунды».','duel','active',null,0,3,3,0,4008),
('duel-format-marathon-4-streak','/achievements/duel-formats/marathon-4-streak-v1.webp?v=20260906-hd1','Победная серия · Марафон · 4 секунды','Самый короткий отсчёт «Марафона» проверяет реакцию снова и снова. Удержи темп не только до конца игры, но и в следующих дуэлях.','Выиграть 2 дуэли подряд в формате «Марафон · 4 секунды».','duel','active',null,0,5,5,0,4009),
('duel-format-marathon-7-wins','/achievements/duel-formats/marathon-7-wins-v1.webp?v=20260906-hd1','Победы · Марафон · 7 секунд','Семь секунд дают время выбрать бросок, но таймер продолжает идти. Находи баланс между скоростью и точностью и выигрывай дуэли.','Выиграть 1 дуэль в формате «Марафон · 7 секунд».','duel','active',null,0,3,3,0,4010),
('duel-format-marathon-7-streak','/achievements/duel-formats/marathon-7-streak-v1.webp?v=20260906-hd1','Победная серия · Марафон · 7 секунд','Ровный темп помогает пройти длинную дуэль. Сделай эту устойчивость привычкой и собери серию побед в «Марафоне» на семь секунд.','Выиграть 2 дуэли подряд в формате «Марафон · 7 секунд».','duel','active',null,0,5,5,0,4011),
('duel-format-rhythm-wins','/achievements/duel-formats/rhythm-wins-v1.webp?v=20260906-hd1','Победы · Ритм','Одиночных голов здесь мало: очки приносят зачётные серии. Свяжи точные броски в длинные отрезки и переиграй соперника.','Выиграть 1 дуэль в формате «Ритм».','duel','active',null,0,3,3,0,4012),
('duel-format-rhythm-streak','/achievements/duel-formats/rhythm-streak-v1.webp?v=20260906-hd1','Победная серия · Ритм','В каждой новой дуэли ритм приходится ловить заново. Собирай зачётные серии и продолжай свою последовательность побед.','Выиграть 2 дуэли подряд в формате «Ритм».','duel','active',null,0,5,5,0,4013),
('duel-sniper-quality','/achievements/duel-formats/sniper-quality-v1.webp?v=20260906-hd1','Качество решает','Соперник забил больше, но твои голы оказались дороже. Выиграй «Снайпера» по очкам за сложность голов.','Выиграть «Снайпера», забив меньше голов, но набрав больше очков, чем соперник.','duel','active',null,0,8,8,0,4014),
('duel-sniper-arsenal','/achievements/duel-formats/sniper-arsenal-v1.webp?v=20260906-hd1','Богатый арсенал','Не ограничивайся любимым броском. За одну дуэль покажи разные техники голов, которые распознаёт игра.','В одной дуэли «Снайпер» забить голы 3 разными техниками.','duel','active',null,0,5,5,0,4015),
('duel-sniper-jeweler','/achievements/duel-formats/sniper-jeweler-v1.webp?v=20260906-hd1','Ювелир','Попасть в самое узкое окно один раз — мастерство. Повтори самый дорогой бросок ещё раз в той же дуэли.','За одну дуэль «Снайпер» дважды забить гол стоимостью ровно 2 очка.','duel','active',null,0,10,10,0,4016),
('duel-marathon-4-clean','/achievements/duel-formats/marathon-4-clean-v1.webp?v=20260906-hd1','Без потерь · Марафон 4 сек','Четыре секунды на следующий гол. Пройди всю дуэль без единого штрафа по таймеру и заверши её победой.','Выиграть «Марафон · 4 секунды», ни разу не получив штраф за истечение таймера.','duel','active',null,0,10,10,0,4017),
('duel-marathon-4-tempo','/achievements/duel-formats/marathon-4-tempo-v1.webp?v=20260906-hd1','Держу темп · Марафон 4 сек','Короткий отсчёт запускается снова после каждого гола. Продолжай эту цепочку, не позволяя таймеру отнять шайбу.','В одной дуэли «Марафон · 4 секунды» забить 5 голов без штрафа по таймеру между ними. Промах сам по себе не сбрасывает прогресс.','duel','active',null,0,3,3,0,4018),
('duel-marathon-7-clean','/achievements/duel-formats/marathon-7-clean-v1.webp?v=20260906-hd1','Без потерь · Марафон 7 сек','Время на прицел есть, но длинная пауза всё равно отнимает шайбу. Выиграй семисекундный «Марафон», ни разу не отдав очко таймеру.','Выиграть «Марафон · 7 секунд», ни разу не получив штраф за истечение таймера.','duel','active',null,0,10,10,0,4019),
('duel-marathon-7-tempo','/achievements/duel-formats/marathon-7-tempo-v1.webp?v=20260906-hd1','Держу темп · Марафон 7 сек','Промах ещё не обрывает удачный отрезок. Успей забить до штрафа и продли свою цепочку голов в семисекундном «Марафоне».','В одной дуэли «Марафон · 7 секунд» забить 5 голов без штрафа по таймеру между ними. Промах сам по себе не сбрасывает прогресс.','duel','active',null,0,3,3,0,4020),
('duel-rhythm-wave','/achievements/duel-formats/rhythm-wave-v1.webp?v=20260906-hd1','Поймал волну','Найди свой ритм и продержись в нём как можно дольше. Каждый следующий гол продолжает одну непрерывную серию.','В одной дуэли «Ритм» собрать непрерывную серию из 4 гола.','duel','active',null,0,3,3,0,4021),
('duel-rhythm-recovery','/achievements/duel-formats/rhythm-recovery-v1.webp?v=20260906-hd1','Снова в такт','Зачётная серия оборвалась, но дуэль продолжается. Соберись и начни новую длинную серию в этой же игре.','В «Ритме» после обрыва серии минимум из четырёх голов собрать в той же дуэли новую серию минимум из 4 гола.','duel','active',null,0,5,5,0,4022),
('duel-rhythm-longer','/achievements/duel-formats/rhythm-longer-v1.webp?v=20260906-hd1','Длиннее — сильнее','Основной счёт равный. Преимущество решит то, насколько длинными были твои голевые серии.','Выиграть «Ритм» при равном основном счёте за счёт сравнения длин серий.','duel','active',null,0,8,8,0,4023),
('duel-universal','/achievements/duel-formats/universal-v1.webp?v=20260906-hd1','Универсальный дуэлянт','Освой все форматы: от точности «Снайпера» до непрерывного «Ритма». Победы нужны в каждом формате, включая оба варианта «Марафона».','Одержать хотя бы одну победу в каждом из семи вариантов: Экспресс, Микс, Классика, Снайпер, Марафон 4 секунды, Марафон 7 секунд и Ритм.','duel','active',null,0,10,10,0,4024);
